import java.util.Arrays;

public final class BubbleSortDemo {
    private static final String USAGE = "Usage: java BubbleSortDemo [integers...]";

    private BubbleSortDemo() {
        // Utility class; do not instantiate.
    }

    public static void main(String[] args) {
        System.exit(run(args));
    }

    private static int run(String[] args) {
        try {
            int[] values = BubbleSortInputParser.parse(args);
            BubbleSort.sort(values);
            System.out.println(Arrays.toString(values));
            return 0;
        } catch (BubbleSortInputException ex) {
            printUsageError(ex.getMessage());
            return 1;
        }
    }

    private static void printUsageError(String message) {
        System.err.println(message);
        System.err.println(USAGE);
    }
}

final class BubbleSortInputParser {
    private BubbleSortInputParser() {
        // Utility class; do not instantiate.
    }

    static int[] parse(String[] args) {
        if (args.length == 0) {
            throw new BubbleSortInputException("No integers provided.");
        }

        int[] values = new int[args.length];

        for (int i = 0; i < args.length; i++) {
            values[i] = parseValue(args[i], i + 1);
        }

        return values;
    }

    private static int parseValue(String arg, int position) {
        try {
            return Integer.parseInt(arg);
        } catch (NumberFormatException ex) {
            throw new BubbleSortInputException(
                    "Invalid integer at argument " + position + ": \"" + arg + "\"");
        }
    }
}

